1	import { createRemoteJWKSet as joseCreateRemoteJWKSet, jwtVerify, decodeJwt } from 'jose';
2	import { getAppOrigin } from '@salesforce/pwa-kit-react-sdk/utils/url';
3	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
4	import type { SsrReq, SsrRes } from './types';
5	
6	const CLAIM = {
7	  ISSUER: 'iss',
8	};
9	
10	const DELIMITER = {
11	  ISSUER: '/',
12	};
13	
14	const tenantIdRegExp = /^[a-zA-Z]{4}_([0-9]{3}|s[0-9]{2}|stg|dev|prd)$/;
15	const shortCodeRegExp = /^[a-zA-Z0-9-]+$/;
16	
17	function throwSlasTokenValidationError(message: string, code: number): never {
18	  throw new Error(`SLAS Token Validation Error: ${message} (${code})`);
19	}
20	
21	type CommerceAPIConfig = {
22	  commerceAPI: {
23	    parameters: { shortCode: string; organizationId: string };
24	  };
25	};
26	
27	export const createRemoteJWKSet = (tenantId: string) => {
28	  const appOrigin = getAppOrigin();
29	  const { app: appConfig } = getConfig() as { app: CommerceAPIConfig };
30	  const shortCode = appConfig.commerceAPI.parameters.shortCode;
31	  const configTenantId = appConfig.commerceAPI.parameters.organizationId.replace(/^f_ecom_/, '');
32	  if (tenantId !== configTenantId) {
33	    throw new Error(
34	      `The tenant ID in your PWA Kit configuration ("${configTenantId}") does not match the tenant ID in the SLAS callback token ("${tenantId}").`,
35	    );
36	  }
37	  const JWKS_URI = `${appOrigin}/${shortCode}/${tenantId}/oauth2/jwks`;
38	  return joseCreateRemoteJWKSet(new URL(JWKS_URI));
39	};
40	
41	export const validateSlasCallbackToken = async (token: string) => {
42	  const payload = decodeJwt(token);
43	  const subClaim = payload[CLAIM.ISSUER] as string;
44	  const tokens = subClaim.split(DELIMITER.ISSUER);
45	  const tenantId = tokens[2];
46	  try {
47	    const jwks = createRemoteJWKSet(tenantId);
48	    const { payload } = await jwtVerify(token, jwks, {});
49	    return payload;
50	  } catch (error) {
51	    throwSlasTokenValidationError((error as Error).message, 401);
52	  }
53	};
