42	/**
43	 * Safely parses settings from either a JSON string or object
44	 * @param {string|object} settings - The settings
45	 * @returns {object} Parsed settings object
46	 */
47	function parseSettings(settings) {
48	  // If settings is already an object, return it
49	  if (typeof settings === 'object' && settings !== null) {
50	    return settings;
51	  }
52	
53	  // If settings is a non-blank string, try to parse it
54	  if (typeof settings === 'string' && settings.trim() !== '') {
55	    try {
56	      return JSON.parse(settings);
57	    } catch (error) {
58	      console.warn('Invalid json format:', error.message);
59	      return;
60	    }
61	  }
62	
63	  return;
64	}
65	
66	module.exports = {
67	  parseSettings,
68	  validateOtpTokenLength,
69	  DEFAULT_OTP_TOKEN_LENGTH,
70	  VALID_OTP_TOKEN_LENGTHS,
71	};
